    private sealed class Factory:WebApplicationFactory<Program>{protected override void ConfigureWebHost(IWebHostBuilder b){b.UseEnvironment("Demo");b.UseSetting("ConnectionStrings:Default",Environment.GetEnvironmentVariable("ACADEMY_TEST_CONNECTION_STRING")??throw new InvalidOperationException("Separate database required"));b.UseSetting("Demo:SeedEnabled","true");b.UseSetting("Demo:SeedProfile","LegacyRegression");b.UseSetting("Demo:StaffPassword","Demo-Only-123!");b.UseSetting("Demo:FixedOtpEnabled","true");b.UseSetting("Demo:FixedOtp","246810");b.UseSetting("Imports:WorkerEnabled","false");b.UseSetting("Notifications:WorkerEnabled","false");}}
    private static async Task<HttpResponseMessage> Write(HttpClient c,string path,object value,bool put=false){var csrf=await c.GetFromJsonAsync<JsonElement>("/api/v1/auth/csrf");var q=new HttpRequestMessage(put?HttpMethod.Put:HttpMethod.Post,path){Content=JsonContent.Create(value)};q.Headers.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return await c.SendAsync(q);}
    private static async Task<HttpClient> Mobile(Factory f,string phone){var c=f.CreateClient();var request=await c.PostAsJsonAsync("/api/v1/mobile/auth/otp/request",new{phoneNumber=phone});request.EnsureSuccessStatusCode();var challenge=await request.Content.ReadFromJsonAsync<JsonElement>();var verified=await c.PostAsJsonAsync("/api/v1/mobile/auth/otp/verify",new{phoneNumber=phone,challengeId=challenge.GetProperty("challengeId").GetGuid(),code="246810",deviceName="Isolated audience test"});verified.EnsureSuccessStatusCode();var tokens=await verified.Content.ReadFromJsonAsync<JsonElement>();c.DefaultRequestHeaders.Authorization=new("Bearer",tokens.GetProperty("accessToken").GetString());return c;}
    [Theory][InlineData("https://chat.whatsapp.com/ABCDEFGHIJKLMNOPQRSTUV",true)][InlineData("https://chat.whatsapp.com.evil.test/ABCDEFGHIJKLMNOPQRSTUV",false)][InlineData("https://evil.test/ABCDEFGHIJKLMNOPQRSTUV",false)][InlineData("https://chat.whatsapp.com/short",false)][InlineData("https://chat.whatsapp.com/ABCDEFGHIJKLMNOPQRSTUV?redirect=https://evil.test",false)]
    public void Invitation_is_an_allowlisted_official_link(string url,bool valid)=>Assert.Equal(valid,AudienceCommunicationEndpoints.ValidInvite(url)!=null);
    [Fact]
    public async Task Audience_uses_distinct_linked_guardians_reauthorizes_preview_and_deep_link_and_deduplicates_retry()
    {
        await using var f=new Factory();using var owner=f.CreateClient();(await Write(owner,"/api/v1/auth/login",new{email=DemoSeed.OwnerEmail,password="Demo-Only-123!"})).EnsureSuccessStatusCode();
        await using var scope=f.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var users=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();var academy=DemoSeed.NogoomAcademyId;var now=DateTimeOffset.UtcNow;var ownerMember=await db.AcademyMemberships.Where(m=>m.AcademyId==academy&&m.Role==AcademyRole.AcademyOwner).Select(m=>new{m.Id,m.UserId}).FirstAsync();var seedGroup=await db.TrainingGroups.FirstAsync(g=>g.AcademyId==academy&&g.IsActive&&g.Branch.IsActive&&g.Sport.IsActive);
        var group=new TrainingGroup{Id=Guid.NewGuid(),AcademyId=academy,ArabicName="مجموعة تواصل خيالية "+Guid.NewGuid().ToString("N")[..8],BranchId=seedGroup.BranchId,SportId=seedGroup.SportId,AgeCategoryId=seedGroup.AgeCategoryId,CreatedAtUtc=now,UpdatedAtUtc=now};db.TrainingGroups.Add(group);
        var phone="+2010"+Random.Shared.Next(10000000,99999999);var user=new ApplicationUser{Id=Guid.NewGuid(),UserName=phone,PhoneNumber=phone,PhoneNumberConfirmed=true,DisplayName="ولي أخوين خيالي",CreatedAtUtc=now,UpdatedAtUtc=now};Assert.True((await users.CreateAsync(user)).Succeeded);var guardian=new GuardianProfile{Id=Guid.NewGuid(),AcademyId=academy,UserId=user.Id,DisplayName=user.DisplayName,ContactPhone=phone,CreatedAtUtc=now,UpdatedAtUtc=now};db.GuardianProfiles.Add(guardian);db.AcademyMemberships.Add(new(){Id=Guid.NewGuid(),AcademyId=academy,UserId=user.Id,Role=AcademyRole.Guardian,CreatedAtUtc=now,UpdatedAtUtc=now});
        var links=new List<GuardianPlayerLink>();var enrollments=new List<SportEnrollment>();
        foreach(var index in new[]{1,2}){var p=new Player{Id=Guid.NewGuid(),AcademyId=academy,PlayerCode="COMM-"+Guid.NewGuid().ToString("N")[..8],ArabicName="طفل تواصل خيالي "+index,DateOfBirth=new(2016,1,1),CreatedAtUtc=now,UpdatedAtUtc=now};db.Players.Add(p);var e=new SportEnrollment{Id=Guid.NewGuid(),AcademyId=academy,PlayerId=p.Id,SportId=group.SportId,BranchId=group.BranchId,TrainingGroupId=group.Id,GroupAssignedFrom=new(2020,1,1),CreatedAtUtc=now,UpdatedAtUtc=now};db.SportEnrollments.Add(e);enrollments.Add(e);var l=new GuardianPlayerLink{Id=Guid.NewGuid(),AcademyId=academy,GuardianId=guardian.Id,PlayerId=p.Id,CreatedByUserId=ownerMember.UserId,CreatedAtUtc=now,UpdatedAtUtc=now};db.GuardianPlayerLinks.Add(l);links.Add(l);}await db.SaveChangesAsync();
        var scheduleDay = DateOnly.FromDateTime(DateTime.UtcNow).AddDays(2);
        var timetable = new TimetableWrite(scheduleDay, scheduleDay.AddDays(7), [scheduleDay.DayOfWeek], new(16,30), new(17,30));
        var timetablePath = $"/api/v1/manage/groups/{group.Id}/timetable";
        var savedSchedule = await Write(owner,timetablePath,timetable); Assert.True(savedSchedule.IsSuccessStatusCode,await savedSchedule.Content.ReadAsStringAsync());
        var automatic = await db.AcademyNotices.Where(n=>n.AcademyId==academy&&n.UserId==user.Id&&n.Message.Contains(group.ArabicName)&&n.Message.Contains("تم تحديث مواعيد")).ToArrayAsync();
        Assert.Single(automatic); Assert.Contains("4:30 مساءً",automatic[0].Message); Assert.DoesNotContain("16:30",automatic[0].Message);
        (await Write(owner,timetablePath,timetable)).EnsureSuccessStatusCode();
        Assert.Equal(1,await db.AcademyNotices.CountAsync(n=>n.AcademyId==academy&&n.UserId==user.Id&&n.Message.Contains(group.ArabicName)&&n.Message.Contains("تم تحديث مواعيد")));
        Assert.False(await db.AcademyNotices.AnyAsync(n=>n.AcademyId==DemoSeed.FutureAcademyId&&n.TargetId==automatic[0].TargetId));

        var path=$"/api/v1/communication/groups/{group.Id}";var initial=await owner.GetFromJsonAsync<JsonElement>(path);Assert.Equal(2,initial.GetProperty("playerCount").GetInt32());Assert.Equal(1,initial.GetProperty("recipientCount").GetInt32());
        var invitation="https://chat.whatsapp.com/ABCDEFGHIJKLMNOPQRSTUV";var saved=await Write(owner,path+"/whatsapp",new{inviteUrl=invitation,expectedVersion=0},true);saved.EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Conflict,(await Write(owner,path+"/whatsapp",new{inviteUrl=invitation,expectedVersion=0},true)).StatusCode);
        var coachPhone="+2010"+Random.Shared.Next(10000000,99999999);var coachUser=new ApplicationUser{Id=Guid.NewGuid(),UserName=coachPhone,PhoneNumber=coachPhone,PhoneNumberConfirmed=true,DisplayName="مدرب تواصل خيالي",CreatedAtUtc=now,UpdatedAtUtc=now};Assert.True((await users.CreateAsync(coachUser)).Succeeded);var coachMembership=new AcademyMembership{Id=Guid.NewGuid(),AcademyId=academy,UserId=coachUser.Id,Role=AcademyRole.Coach,CreatedAtUtc=now,UpdatedAtUtc=now};db.AcademyMemberships.Add(coachMembership);var assignment=new StaffGroupAssignment{Id=Guid.NewGuid(),AcademyId=academy,AcademyMembershipId=coachMembership.Id,TrainingGroupId=group.Id,CreatedAtUtc=now,UpdatedAtUtc=now};db.StaffGroupAssignments.Add(assignment);await db.SaveChangesAsync();
        using var coach=await Mobile(f,coachPhone);Assert.False((await coach.GetFromJsonAsync<JsonElement>(path)).GetProperty("canSend").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await coach.PostAsJsonAsync(path+"/preview",new{message="تنبيه المدرب",requestId=Guid.NewGuid()})).StatusCode);
        var version=(await saved.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("version").GetUInt32();(await Write(owner,path+"/whatsapp",new{inviteUrl=invitation,expectedVersion=version,coachCanSend=true},true)).EnsureSuccessStatusCode();Assert.True((await coach.GetFromJsonAsync<JsonElement>(path)).GetProperty("canSend").GetBoolean());(await coach.PostAsJsonAsync(path+"/preview",new{message="تنبيه المدرب",requestId=Guid.NewGuid()})).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Forbidden,(await coach.PutAsJsonAsync(path+"/whatsapp",new{inviteUrl=invitation,expectedVersion=version})).StatusCode);assignment.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(path)).StatusCode);
        using var parent=await Mobile(f,phone);(await parent.PutAsJsonAsync("/api/v1/mobile-push/device",new PushDeviceWrite("APNs",Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N")))).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Forbidden,(await parent.GetAsync(path)).StatusCode);
        var id=Guid.NewGuid();var command=new{message="تذكير عام بالحصة غدًا",requestId=id,includeInvitation=true};var previewResponse=await Write(owner,path+"/preview",command);previewResponse.EnsureSuccessStatusCode();var preview=await previewResponse.Content.ReadFromJsonAsync<JsonElement>();Assert.Equal(1,preview.GetProperty("recipientCount").GetInt32());var send=new{command.message,command.requestId,command.includeInvitation,previewHash=preview.GetProperty("previewHash").GetString()};
        var sent=await Write(owner,path+"/send",send);sent.EnsureSuccessStatusCode();var announcement=await sent.Content.ReadFromJsonAsync<JsonElement>();var announcementId=announcement.GetProperty("id").GetGuid();var repeat=await Write(owner,path+"/send",send);repeat.EnsureSuccessStatusCode();Assert.True((await repeat.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("replay").GetBoolean());Assert.Equal(1,await db.AcademyNotices.CountAsync(n=>n.TargetId==announcementId));Assert.Equal(1,await db.NoticeDispatches.CountAsync(n=>n.RequestId==id));var queued=await db.MobilePushDeliveries.Where(d=>db.AcademyNotices.Any(n=>n.Id==d.NoticeId&&n.TargetId==announcementId)).Select(d=>d.Id).ToArrayAsync();Assert.Single(queued);
        var inbox=await parent.GetFromJsonAsync<JsonElement>("/api/v1/notifications");var notice=Assert.Single(inbox.GetProperty("items").EnumerateArray(),n=>n.GetProperty("targetId").ValueKind==JsonValueKind.String&&n.GetProperty("targetId").GetGuid()==announcementId);Assert.DoesNotContain("chat.whatsapp.com",notice.GetProperty("message").GetString());
        var detailPath=$"/api/v1/communication/announcements/{announcementId}";var detail=await parent.GetFromJsonAsync<JsonElement>(detailPath);Assert.Equal(invitation,detail.GetProperty("inviteUrl").GetString());
        var foreign=await db.TrainingGroups.Where(g=>g.AcademyId==DemoSeed.FutureAcademyId).Select(g=>g.Id).FirstAsync();Assert.Equal(HttpStatusCode.NotFound,(await owner.GetAsync($"/api/v1/communication/groups/{foreign}")).StatusCode);
        var changedId=Guid.NewGuid();var other=await Write(owner,path+"/preview",new{message="معاينة تتغير",requestId=changedId});other.EnsureSuccessStatusCode();var quoted=await other.Content.ReadFromJsonAsync<JsonElement>();foreach(var link in links)link.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await parent.GetAsync(detailPath)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await parent.GetAsync($"/api/v1/mobile-push/notices/{notice.GetProperty("id").GetGuid()}")).StatusCode);await using(var deliveryScope=f.Services.CreateAsyncScope()){await MobilePushWorker.ProcessOne(deliveryScope.ServiceProvider,CancellationToken.None,queued.Single());}Assert.Equal("Suppressed",await db.MobilePushDeliveries.Where(d=>d.Id==queued.Single()).Select(d=>d.State).SingleAsync());
        var changed=await Write(owner,path+"/send",new{message="معاينة تتغير",requestId=changedId,previewHash=quoted.GetProperty("previewHash").GetString()});Assert.Equal(HttpStatusCode.Conflict,changed.StatusCode);
        Assert.Equal(1,await db.AudienceAnnouncements.CountAsync(a=>a.Id==announcementId));Assert.Equal(2,await db.AudienceLinkAudits.CountAsync(a=>a.CommunicationId==db.AudienceCommunications.Where(c=>c.TrainingGroupId==group.Id).Select(c=>c.Id).Single()));
    }
    [Fact]
    public async Task Team_event_uses_published_event_roster_and_reports_real_prefill()
    {
        await using var f=new Factory();using var owner=f.CreateClient();(await Write(owner,"/api/v1/auth/login",new{email=DemoSeed.OwnerEmail,password="Demo-Only-123!"})).EnsureSuccessStatusCode();
        await using var scope=f.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var academy=DemoSeed.NogoomAcademyId;var now=DateTimeOffset.UtcNow;var g=await db.TrainingGroups.FirstAsync(x=>x.AcademyId==academy&&x.IsActive&&x.Branch.IsActive&&x.Sport.IsActive);var enrollments=await db.SportEnrollments.Where(e=>e.AcademyId==academy&&e.SportId==g.SportId&&e.BranchId==g.BranchId&&e.IsActive).Take(2).ToArrayAsync();Assert.NotEmpty(enrollments);
        var team=new MatchTeam{Id=Guid.NewGuid(),AcademyId=academy,Name="فريق تواصل خيالي "+Guid.NewGuid().ToString("N")[..8],SportId=g.SportId,BranchId=g.BranchId,AgeCategoryId=g.AgeCategoryId,CoachMembershipId=await db.AcademyMemberships.Where(m=>m.AcademyId==academy&&m.Role==AcademyRole.Coach&&m.IsActive).Select(m=>m.Id).FirstAsync(),CreatedAtUtc=now,UpdatedAtUtc=now};db.MatchTeams.Add(team);foreach(var e in enrollments)db.MatchTeamPlayers.Add(new(){Id=Guid.NewGuid(),AcademyId=academy,TeamId=team.Id,EnrollmentId=e.Id,CreatedAtUtc=now,UpdatedAtUtc=now});
        var tournament=new AcademyTournament{Id=Guid.NewGuid(),AcademyId=academy,Name="بطولة تواصل خيالية "+Guid.NewGuid().ToString("N")[..8],SportId=g.SportId,Fee=12.5m,Currency="EGP",CreatedAtUtc=now,UpdatedAtUtc=now};db.AcademyTournaments.Add(tournament);var match=new AcademyMatch{Id=Guid.NewGuid(),AcademyId=academy,TeamId=team.Id,TournamentId=tournament.Id,Opponent="فريق عرض",MatchDate=DateOnly.FromDateTime(now.UtcDateTime.AddDays(2)),StartTime=new(16,0),Venue="ملعب عرض خيالي",PublishedAtUtc=now,PublishedFingerprint="isolated-communication-test",CreatedAtUtc=now,UpdatedAtUtc=now};db.AcademyMatches.Add(match);db.MatchParticipants.Add(new(){Id=Guid.NewGuid(),AcademyId=academy,MatchId=match.Id,PlayerId=enrollments[0].PlayerId,CreatedAtUtc=now,UpdatedAtUtc=now});await db.SaveChangesAsync();
        var path=$"/api/v1/communication/teams/{team.Id}";var info=await owner.GetFromJsonAsync<JsonElement>(path);Assert.Equal(enrollments.Select(e=>e.PlayerId).Distinct().Count(),info.GetProperty("playerCount").GetInt32());Assert.Equal(12.5m,info.GetProperty("nextEvent").GetProperty("fee").GetDecimal());
        var preview=await Write(owner,path+"/preview",new{message="موعد الفريق العام",requestId=Guid.NewGuid(),matchId=match.Id});preview.EnsureSuccessStatusCode();Assert.Equal(1,(await preview.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("playerCount").GetInt32());
        Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(owner,path+"/preview",new{message="موعد",requestId=Guid.NewGuid(),matchId=Guid.NewGuid()})).StatusCode);
        match.PublishedAtUtc=null;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.UnprocessableEntity,(await Write(owner,path+"/preview",new{message="مسودة",requestId=Guid.NewGuid(),matchId=match.Id})).StatusCode);
    }

